require_once __DIR__ . '/_layout.php';requirePermission('maintenance.manage');
if(requestMethod()==='POST'){requireCsrfPost();$action=$_POST['action']??'';try{if($action==='create'){$vehicle=dbFetchOne('SELECT * FROM vehicles WHERE id=:id',['id'=>(int)$_POST['vehicle_id']]);if(!$vehicle)throw new InvalidArgumentException('Vehicle not found.');requireAgencyAccess($vehicle['agency_id']);dbExecute('INSERT INTO maintenance_records(vehicle_id,maintenance_type,description,garage,supplier,current_mileage,scheduled_mileage,scheduled_date,entry_at,estimated_exit_at,cost,replaced_parts,next_maintenance_date,next_maintenance_mileage,status,created_by,updated_by)VALUES(:vehicle,:type,:description,:garage,:supplier,:mileage,:scheduled_mileage,:scheduled_date,:entry_at,:estimated_exit,:cost,:parts,:next_date,:next_mileage,:status,:user,:user2)',['vehicle'=>$vehicle['id'],'type'=>validateChoice($_POST['maintenance_type']??'',['oil_change','filters','tyres','brakes','battery','air_conditioning','technical_inspection','repair','other'],'other'),'description'=>trim((string)($_POST['description']??'')),'garage'=>trim((string)($_POST['garage']??'')),'supplier'=>trim((string)($_POST['supplier']??'')),'mileage'=>$vehicle['current_mileage'],'scheduled_mileage'=>(int)($_POST['scheduled_mileage']??0)?:null,'scheduled_date'=>($_POST['scheduled_date']??'')?:null,'entry_at'=>($_POST['entry_at']??'')?:null,'estimated_exit'=>($_POST['estimated_exit_at']??'')?:null,'cost'=>positiveMoney($_POST['cost']??'0')??'0.00','parts'=>trim((string)($_POST['replaced_parts']??'')),'next_date'=>($_POST['next_maintenance_date']??'')?:null,'next_mileage'=>(int)($_POST['next_maintenance_mileage']??0)?:null,'status'=>validateChoice($_POST['status']??'',['scheduled','in_progress'],'scheduled'),'user'=>currentUserId(),'user2'=>currentUserId()]);$id=(int)db()->lastInsertId();if($_POST['status']==='in_progress')dbExecute("UPDATE vehicles SET status='maintenance',updated_by=:user WHERE id=:id",['user'=>currentUserId(),'id'=>$vehicle['id']]);auditLog('maintenance.created','maintenance_record',$id,null,['vehicle_id'=>$vehicle['id'],'status'=>$_POST['status']],$vehicle['agency_id']);flash('success','Maintenance record created.');}elseif($action==='status'){$record=dbFetchOne('SELECT m.*,v.agency_id FROM maintenance_records m JOIN vehicles v ON v.id=m.vehicle_id WHERE m.id=:id',['id'=>(int)$_POST['id']]);if(!$record)throw new InvalidArgumentException('Maintenance record not found.');requireAgencyAccess($record['agency_id']);$status=validateChoice($_POST['status']??'',['scheduled','in_progress','completed','cancelled'],'');if(!$status)throw new InvalidArgumentException('Invalid maintenance status.');withTransaction(function()use($record,$status){dbExecute('UPDATE maintenance_records SET status=:status,entry_at=IF(:s2=\'in_progress\',COALESCE(entry_at,NOW()),entry_at),actual_exit_at=IF(:s3=\'completed\',NOW(),actual_exit_at),updated_by=:user WHERE id=:id',['status'=>$status,'s2'=>$status,'s3'=>$status,'user'=>currentUserId(),'id'=>$record['id']]);if($status==='in_progress')dbExecute("UPDATE vehicles SET status='maintenance',updated_by=:user WHERE id=:id",['user'=>currentUserId(),'id'=>$record['vehicle_id']]);elseif(in_array($status,['completed','cancelled'],true))dbExecute("UPDATE vehicles SET status='available',updated_by=:user WHERE id=:id AND status='maintenance'",['user'=>currentUserId(),'id'=>$record['vehicle_id']]);});auditLog('maintenance.status_changed','maintenance_record',$record['id'],['status'=>$record['status']],['status'=>$status],$record['agency_id']);flash('success','Maintenance status updated.');}elseif($action==='document'){$vehicle=dbFetchOne('SELECT * FROM vehicles WHERE id=:id',['id'=>(int)$_POST['vehicle_id']]);if(!$vehicle)throw new InvalidArgumentException('Vehicle not found.');requireAgencyAccess($vehicle['agency_id']);$stored=storeValidatedDocument($_FILES['document'],'vehicle_documents');dbExecute('INSERT INTO vehicle_documents(vehicle_id,document_type,document_number,issued_at,expires_at,storage_path,original_name,mime_type,file_size,created_by)VALUES(:vehicle,:type,:number,:issued,:expires,:path,:original,:mime,:size,:user)',['vehicle'=>$vehicle['id'],'type'=>validateChoice($_POST['document_type']??'',['registration','insurance','technical_inspection','tax','other'],'other'),'number'=>trim((string)($_POST['document_number']??'')),'issued'=>($_POST['issued_at']??'')?:null,'expires'=>($_POST['expires_at']??'')?:null,'path'=>$stored['path'],'original'=>$stored['original_name'],'mime'=>$stored['mime_type'],'size'=>$stored['size'],'user'=>currentUserId()]);auditLog('vehicle_document.created','vehicle_document',db()->lastInsertId(),null,['vehicle_id'=>$vehicle['id'],'type'=>$_POST['document_type']],$vehicle['agency_id']);flash('success','Vehicle document stored.');}}catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Maintenance operation failed');flash('danger','The maintenance operation could not be completed.');}safeRedirect('maintenance.php');}
$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$vehicles=dbFetchAll("SELECT id,registration_number,brand,model,current_mileage FROM vehicles WHERE agency_id IN ($ph) AND archived_at IS NULL ORDER BY registration_number",$ids);$records=dbFetchAll("SELECT m.*,v.registration_number,v.brand,v.model FROM maintenance_records m JOIN vehicles v ON v.id=m.vehicle_id WHERE v.agency_id IN ($ph) AND m.archived_at IS NULL ORDER BY COALESCE(m.scheduled_date,DATE(m.entry_at)) DESC LIMIT 100",$ids);$documents=dbFetchAll("SELECT vd.*,v.registration_number FROM vehicle_documents vd JOIN vehicles v ON v.id=vd.vehicle_id WHERE v.agency_id IN ($ph) AND vd.archived_at IS NULL ORDER BY vd.expires_at LIMIT 100",$ids);
backofficeHeader(t('maintenance'),'maintenance.php');?><div class="page-head"><h1>Maintenance and vehicle documents</h1></div><div class="grid"><section class="card"><h2>Schedule maintenance</h2><form method="post"><?=csrfField()?><input type="hidden" name="action" value="create"><label>Vehicle<select name="vehicle_id"><?php foreach($vehicles as $v):?><option value="<?=e($v['id'])?>"><?=e($v['registration_number'].' — '.$v['brand'].' '.$v['model'])?></option><?php endforeach;?></select></label><label>Type<select name="maintenance_type"><?php foreach(['oil_change','filters','tyres','brakes','battery','air_conditioning','technical_inspection','repair','other'] as $type):?><option><?=e($type)?></option><?php endforeach;?></select></label><label>Status<select name="status"><option>scheduled</option><option>in_progress</option></select></label><label>Scheduled date<input type="date" name="scheduled_date"></label><label>Entry time<input type="datetime-local" name="entry_at"></label><label>Estimated exit<input type="datetime-local" name="estimated_exit_at"></label><label>Garage<input name="garage"></label><label>Supplier<input name="supplier"></label><label>Estimated/final cost<input name="cost" inputmode="decimal"></label><label>Description<textarea name="description"></textarea></label><label>Next maintenance date<input type="date" name="next_maintenance_date"></label><label>Next mileage<input type="number" name="next_maintenance_mileage"></label><button class="btn primary">Save maintenance</button></form><hr><h2>Add vehicle document</h2><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="document"><label>Vehicle<select name="vehicle_id"><?php foreach($vehicles as $v):?><option value="<?=e($v['id'])?>"><?=e($v['registration_number'])?></option><?php endforeach;?></select></label><label>Document type<select name="document_type"><option>registration</option><option>insurance</option><option>technical_inspection</option><option>tax</option><option>other</option></select></label><label>Number<input name="document_number"></label><label>Issue date<input type="date" name="issued_at"></label><label>Expiry date<input type="date" name="expires_at"></label><label>PDF or image<input type="file" name="document" accept="application/pdf,image/jpeg,image/png,image/webp" required></label><button class="btn primary">Store document</button></form></section><section class="card"><h2>Maintenance register</h2><div class="table-wrap"><table><tr><th>Vehicle</th><th>Type</th><th>Schedule</th><th>Cost</th><th>Status</th></tr><?php foreach($records as $r):?><tr><td><?=e($r['registration_number'])?></td><td><?=e($r['maintenance_type'])?></td><td><?=e($r['scheduled_date'])?><br><?=e($r['entry_at'])?> → <?=e($r['estimated_exit_at'])?></td><td><?=money($r['cost'])?></td><td><form method="post"><?=csrfField()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=e($r['id'])?>"><select name="status" onchange="this.form.submit()"><?php foreach(['scheduled','in_progress','completed','cancelled'] as $s):?><option <?=$s===$r['status']?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?></table></div><h2>Document expiration</h2><div class="table-wrap"><table><tr><th>Vehicle</th><th>Document</th><th>Expires</th><th>Alert</th></tr><?php foreach($documents as $d):$days=$d['expires_at']?(new DateTimeImmutable('today'))->diff(new DateTimeImmutable($d['expires_at']))->format('%r%a'):null;?><tr><td><?=e($d['registration_number'])?></td><td><?=e($d['document_type'])?></td><td><?=e($d['expires_at'])?></td><td><?=is_numeric($days)&&$days<=30?statusBadge($days<0?'expired':'pending'):''?></td></tr><?php endforeach;?></table></div></section></div><?php backofficeFooter();

